# Let me visualize each region separately with proper bbox
def find_regions(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    bg_val = 8
    all_points = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg_val:
                all_points.append((r, c, grid[r][c]))

    # Group by value and find bounding boxes
    regions = {}
    for r, c, val in all_points:
        if val not in regions:
            regions[val] = {'points': [], 'bbox': [float('inf'), float('inf'), float('-inf'), float('-inf')]}
        regions[val]['points'].append((r, c))
        regions[val]['bbox'][0] = min(regions[val]['bbox'][0], r)
        regions[val]['bbox'][1] = min(regions[val]['bbox'][1], c)
        regions[val]['bbox'][2] = max(regions[val]['bbox'][2], r)
        regions[val]['bbox'][3] = max(regions[val]['bbox'][3], c)

    return regions

