def count_vals_in_rect(grid, rows, cols, r_start=0, c_start=0):
    counts = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r_start+r][c_start+c]
            if val not in counts:
                counts[val] = 0
            counts[val] += 1
    return counts

